import React, { useEffect, useState } from "react";
import axios from "axios";

export default function PaymentNumber() {
  const [bkash, setBkash] = useState("");
  const [nagad, setNagad] = useState("");
  const [role, setRole] = useState("");

  // ✅ টোকেন localStorage থেকে নেওয়া
  const authToken = localStorage.getItem("authToken");

  useEffect(() => {
    if (!authToken) return;

    // 1️⃣ ইউজার প্রোফাইল নিয়ে role সেট করা
    axios
      .get("http://localhost:8080/api/user/profile", {
        headers: { Authorization: `Bearer ${authToken}` },
      })
      .then((res) => {
        setRole(res.data.role || "");
      })
      .catch((err) => {
        console.error("Error fetching profile:", err);
        alert("প্রোফাইল লোড করতে ব্যর্থ হয়েছে");
      });

    // 2️⃣ পেমেন্ট নাম্বার লোড করা
    axios
      .get("http://localhost:8080/api/payment-config", {
        headers: { Authorization: `Bearer ${authToken}` },
      })
      .then((res) => {
        const data = res.data;
        const bkashConfig = data.find((c) => c.method === "bKash");
        const nagadConfig = data.find((c) => c.method === "Nagad");

        if (bkashConfig) setBkash(bkashConfig.number);
        if (nagadConfig) setNagad(nagadConfig.number);
      })
      .catch((err) => console.error("Error loading payment configs:", err));
  }, [authToken]);

  // ✅ শুধু অ্যাডমিন আপডেট করতে পারবে
  const saveNumber = (method, number) => {
    if (!number) {
      alert("❌ নাম্বার দিতে হবে");
      return;
    }

    axios
      .post(
        "http://localhost:8080/api/payment-config/admin/update",
        null,
        {
          params: { method, number },
          headers: { Authorization: `Bearer ${authToken}` },
        }
      )
      .then(() => alert(`✅ ${method} নাম্বার আপডেট হয়েছে`))
      .catch((err) => {
        console.error("Error saving payment number:", err);
        if (err.response && err.response.status === 403) {
          alert("❌ অনুমতি নেই (শুধু অ্যাডমিন আপডেট করতে পারবে)");
        } else {
          alert("❌ আপডেট ব্যর্থ হয়েছে");
        }
      });
  };

  // 🔹 UI Render Helper
  const renderField = (label, color, value, setValue, method) => (
    <div
      style={{
        border: "1px solid #ccc",
        padding: "15px",
        borderRadius: "5px",
        marginBottom: "20px",
        backgroundColor: "#f9f9f9",
      }}
    >
      <h3 style={{ marginBottom: "10px", color }}>{label}</h3>
      <input
        type="text"
        value={value}
        placeholder={`Enter ${label}`}
        onChange={(e) => setValue(e.target.value)}
        disabled={role.toUpperCase() !== "ADMIN"} // শুধু অ্যাডমিন এডিট করতে পারবে
        style={{
          width: "100%",
          padding: "8px",
          border: "1px solid #ccc",
          borderRadius: "4px",
          marginBottom: "8px",
        }}
      />
      {role.toUpperCase() === "ADMIN" && (
        <button
          onClick={() => saveNumber(method, value)}
          style={{
            backgroundColor: color,
            color: "white",
            padding: "8px 15px",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
          }}
        >
          Save {label}
        </button>
      )}
    </div>
  );

  return (
    <div style={{ padding: "20px", maxWidth: "500px", margin: "auto" }}>
      <h2 style={{ textAlign: "center" }}>💳 Payment Number Settings</h2>

      {renderField("বিকাশ নাম্বার", "#d81b60", bkash, setBkash, "bKash")}
      {renderField("নগদ নাম্বার", "#ff6f00", nagad, setNagad, "Nagad")}
    </div>
  );
}
